dev-browser --headless <<'EOF' 2>&1 | tail -20
const page = await browser.getPage("lumail");
await page.setViewportSize({ width: 1600, height: 1000 });
await page.goto("https://lumail.io", { waitUntil: "networkidle" });
await page.waitForTimeout(2500);
const shots = [];
for (let i = 0; i < 8; i++) {
  await page.evaluate((y) => window.scrollTo(0, y), i * 1000);
  await page.waitForTimeout(900);
  const buf = await page.screenshot();
  shots.push(await saveScreenshot(buf, `lumail-${i}.png`));
}
const logo = await page.evaluate(() => {
  const a = document.querySelector('header a, nav a');
  return a ? a.outerHTML.slice(0, 5000) : null;
});
const h1 = await page.evaluate(() => { const h = document.querySelector('h1'); return h ? h.outerHTML.slice(0, 8000) : null; });
await writeFile("logo.html", logo || "");
await writeFile("h1.html", h1 || "");
console.log(JSON.stringify({ title: await page.title(), url: page.url(), shots }));
EOF

