  const k = pr(t, t0, 0.55, E.out);
  if (t < t0 || k >= 1) return null;
  const r = 12 + k * 70;
  return (
    <div
      style={{
        position: 'absolute',
        left: x - r,
        top: y - r,
        width: r * 2,
