import {Easing, interpolate, interpolateColors, spring} from 'remotion';
import {loadFont as loadGeist} from '@remotion/google-fonts/Geist';
import {loadFont as loadGeistMono} from '@remotion/google-fonts/GeistMono';

export const FPS = 60;
export const W = 1920;
export const H = 1080;

export const sans = loadGeist('normal', {
  weights: ['400', '500', '600', '700'],
  subsets: ['latin'],
}).fontFamily;
export const mono = loadGeistMono('normal', {
  weights: ['400', '500'],
  subsets: ['latin'],
}).fontFamily;

// Lumail design tokens, lifted from lumail.io globals.css
export const C = {
  paper: '#f8f7f4',
  ink: '#1a1614',
  void: '#08090a',
  flare: '#ff3300',
  accent: '#c4320a',
  accentDark: '#ff633d',
  coral: '#f26a4b',
  wash: '#fbeee7',
  peach: '#ffe3d9',
  accentBg: '#fff1ec',
  card: '#ffffff',
  border: '#e6e1da',
  muted: '#5f5853',
  mutedDark: '#8a8f98',
  secondary: '#f0ede8',
  mutedBg: '#f2f0ec',
  green: '#0e9f6e',
  greenDark: '#3fbd87',
  white: '#f7f8f8',
};

export const E = {
  out: Easing.bezier(0.16, 1, 0.3, 1),
  outSoft: Easing.bezier(0.22, 1, 0.36, 1),
  inOut: Easing.bezier(0.83, 0, 0.17, 1),
  inOutSoft: Easing.bezier(0.65, 0, 0.35, 1),
  in: Easing.bezier(0.7, 0, 0.84, 0),
  inSoft: Easing.bezier(0.55, 0, 1, 0.45),
  linear: Easing.linear,
};

export const tw = (
  t: number,
  t0: number,
  t1: number,
  a: number,
  b: number,
  ease: (x: number) => number = E.out,
) =>
  interpolate(t, [t0, t1], [a, b], {
    easing: ease,
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

export const pr = (t: number, t0: number, dur: number, ease: (x: number) => number = E.out) =>
  tw(t, t0, t0 + dur, 0, 1, ease);

export const sp = (
  t: number,
  t0: number,
  config: {damping?: number; stiffness?: number; mass?: number} = {},
) =>
  t <= t0
    ? 0
    : spring({
        frame: (t - t0) * FPS,
        fps: FPS,
        config: {damping: 14, stiffness: 170, mass: 0.7, ...config},
      });

export const mix = (a: number, b: number, k: number) => a + (b - a) * k;

export const colorMix = (a: string, b: string, k: number) =>
  interpolateColors(Math.min(1, Math.max(0, k)), [0, 1], [a, b]);

export const typed = (text: string, t: number, t0: number, cps: number) =>
  text.slice(0, Math.max(0, Math.min(text.length, Math.floor((t - t0) * cps))));

export const fmt = (n: number) => Math.round(n).toLocaleString('en-US');

export const blink = (t: number, rate = 2) => (Math.floor(t * rate * 2) % 2 === 0 ? 1 : 0);
import React from 'react';
import {AbsoluteFill, Sequence, useCurrentFrame} from 'remotion';
import {Background} from './Background';
import {Hud} from './Hud';
import {FPS} from './lib';
import {Problem} from './scenes/Problem';
import {Reveal} from './scenes/Reveal';
import timeline from './timeline.json';

type SceneName = keyof typeof timeline.scenes;

const Inner: React.FC<{pre: number; Scene: React.FC<{t: number}>}> = ({pre, Scene}) => {
  const frame = useCurrentFrame();
  return <Scene t={frame / FPS - pre} />;
};

// Mounts a scene over its timeline slot; `pre`/`post` add overlap for transitions
const Slot: React.FC<{name: SceneName; Scene: React.FC<{t: number}>; pre?: number; post?: number}> = ({
  name,
  Scene,
  pre = 0,
  post = 0,
}) => {
  const [a, b] = timeline.scenes[name];
  return (
    <Sequence
      name={name}
      from={Math.round((a - pre) * FPS)}
      durationInFrames={Math.round((b - a + pre + post) * FPS)}
    >
      <Inner pre={pre} Scene={Scene} />
    </Sequence>
  );
};

export const Main: React.FC = () => (
  <AbsoluteFill style={{background: '#f8f7f4'}}>
    <Background />
    <Slot name="problem" Scene={Problem} />
    <Slot name="reveal" Scene={Reveal} />
    <Hud />
  </AbsoluteFill>
);
import {AbsoluteFill, useCurrentFrame} from 'remotion';
import {Lockup} from './components';
import {C, E, FPS, colorMix, mono, pr, tw} from './lib';

const chapters: [number, string, string][] = [
  [11, '01', 'Agents'],
  [17, '02', 'Editor'],
  [23, '03', 'Workflows'],
  [29, '04', 'Transactional'],
  [34, '05', 'Pricing'],
  [39, '06', 'Migrate'],
];

// Top bar: lockup, hairline, and a rolling chapter label
export const Hud: React.FC = () => {
  const t = useCurrentFrame() / FPS;
  const show = pr(t, 11.05, 0.7, E.out) * (1 - pr(t, 41.35, 0.45, E.in));
  if (show <= 0) return null;
  const dark = tw(t, 28.9, 29.0, 0, 1, E.linear) * (1 - tw(t, 33.9, 34.0, 0, 1, E.linear));
  const fg = colorMix(C.ink, C.white, dark);
  const line = dark > 0.5 ? 'rgba(255,255,255,0.1)' : C.border;
  return (
    <AbsoluteFill style={{pointerEvents: 'none'}}>
      <div
        style={{
          position: 'absolute',
          left: 140,
          right: 140,
          top: 44,
          height: 44,
          display: 'flex',
          alignItems: 'center',
          opacity: show,
          transform: `translateY(${(1 - show) * -16}px)`,
        }}
      >
        <Lockup size={38} color={fg} />
        <div style={{flex: 1}} />
        <div style={{position: 'relative', height: 30, width: 420, overflow: 'hidden'}}>
          {chapters.map(([start, num, label], i) => {
            const next = chapters[i + 1]?.[0] ?? 99;
            const kin = pr(t, start - 0.05, 0.55, E.out);
            const kout = pr(t, next - 0.2, 0.4, E.in);
            if (t < start - 0.1 || t > next + 0.3) return null;
            return (
              <div
                key={num}
                style={{
                  position: 'absolute',
                  right: 0,
                  top: 0,
                  display: 'flex',
                  alignItems: 'center',
                  gap: 14,
                  fontFamily: mono,
                  fontSize: 20,
                  letterSpacing: '0.14em',
                  textTransform: 'uppercase',
                  color: fg,
                  transform: `translateY(${(1 - kin) * 30 - kout * 30}px)`,
                  opacity: kin * (1 - kout),
                }}
              >
                <span style={{width: 8, height: 8, borderRadius: 8, background: C.flare}} />
                <span style={{opacity: 0.55}}>{num}</span>
                <span>{label}</span>
              </div>
            );
          })}
        </div>
      </div>
      <div
        style={{
          position: 'absolute',
          left: 72,
          right: 72,
          top: 112,
          height: 1,
          background: line,
          transform: `scaleX(${show})`,
          transformOrigin: 'left center',
        }}
      />
    </AbsoluteFill>
  );
};
import {useLayoutEffect, useState} from 'react';
import {continueRender, delayRender} from 'remotion';

export type TextSpec = {text: string; weight: number; size: number; family: string; tracking?: number};

// Measures text widths once fonts are ready, holding the render until it is done
export const useTextWidths = (specs: TextSpec[]) => {
  const [handle] = useState(() => delayRender('measure text'));
  const [widths, setWidths] = useState<number[] | null>(null);
  useLayoutEffect(() => {
    let alive = true;
    Promise.all(specs.map((s) => document.fonts.load(`${s.weight} ${s.size}px "${s.family}"`)))
      .then(() => document.fonts.ready)
      .then(() => {
        const ctx = document.createElement('canvas').getContext('2d')!;
        const out = specs.map((s) => {
          ctx.font = `${s.weight} ${s.size}px "${s.family}"`;
          (ctx as unknown as {letterSpacing: string}).letterSpacing = `${(s.tracking ?? 0) * s.size}px`;
          return ctx.measureText(s.text).width;
        });
        if (alive) setWidths(out);
        continueRender(handle);
      });
    return () => {
      alive = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return widths;
};
import {AbsoluteFill, useCurrentFrame} from 'remotion';
import {C, E, FPS, pr} from './lib';

const hatch = 'repeating-linear-gradient(135deg, rgba(26,22,20,0.075) 0 1.2px, transparent 1.2px 12px)';

export const RAIL = 72;

// Paper backdrop with the hatched side rails of lumail.io
export const Background: React.FC = () => {
  const t = useCurrentFrame() / FPS;
  const k = pr(t, 0.05, 0.9, E.out);
  const rail = (side: 'left' | 'right') => (
    <div
      style={{
        position: 'absolute',
        top: 0,
        bottom: 0,
        [side]: 0,
        width: RAIL,
        background: hatch,
        [side === 'left' ? 'borderRight' : 'borderLeft']: `1px solid ${C.border}`,
        transform: `scaleY(${k})`,
        transformOrigin: side === 'left' ? 'center top' : 'center bottom',
      }}
    />
  );
  return (
    <AbsoluteFill style={{background: C.paper}}>
      {rail('left')}
      {rail('right')}
    </AbsoluteFill>
  );
};

